package com.priperi;
import org.json.*;import java.io.*;import java.security.*;import java.security.spec.PKCS8EncodedKeySpec;import java.util.*;
/** Offline encrypted recovery kit; current password and both device signatures remain required by server. */
final class AccountRecovery {
 static final class Offer implements AutoCloseable{final byte[] words;final File file;final JSONObject registration;Offer(byte[] words,File file,JSONObject registration){this.words=words;this.file=file;this.registration=registration;}public void close(){Arrays.fill(words,(byte)0);file.delete();}}
 static String proof(Vault v)throws Exception{return TransferCipher.hash(v.identity().getString("deviceSecret").getBytes(Crypto.UTF8));}
 static Offer prepare(Vault v,File destination,boolean chats,char[] password)throws Exception{
  if(v.account()==null||v.transferIn()!=null||v.transferOut()!=null)throw new SecurityException("Finish the current account move first.");Session.continueAccount(v,null,new String(password));
  Repository.call(v,"getRecoveryStatus",new JSONObject()); // Fail closed on an older backend before making an unusable kit.
  JSONObject profile=Repository.call(v,"getAccount",new JSONObject());Crypto.verifyProfile(profile);JSONArray chain=new JSONArray(profile.optJSONArray("delegations")==null?"[]":profile.getJSONArray("delegations").toString());if(chain.length()>30)throw new SecurityException("This account reached its supported recovery/move limit.");
  String id=UUID.randomUUID().toString();KeyPair authorizer=KeyDelegation.temporaryKey();chain.put(v.crypto().authorize(v.identity(),profile.getString("uid"),KeyDelegation.publicValue(authorizer)));
  byte[] words=TransferPhrase.fresh(),historyKey=new byte[32];new SecureRandom().nextBytes(historyKey);File history=v.transferFile(TransferCipher.hash(("recovery:"+id).getBytes(Crypto.UTF8)));
  try{JSONObject identity=new JSONObject();for(String field:new String[]{"private","hpke","signing","fingerprint"})identity.put(field,v.identity().getString(field));identity.put("historySecret",v.identity().optString("historySecret",v.identity().getString("deviceSecret")));
   JSONObject core=new JSONObject().put("version",1).put("id",id).put("uid",profile.getString("uid")).put("profile",profile).put("identity",identity).put("chain",chain).put("authorizer",Crypto.b64(authorizer.getPrivate().getEncoded())).put("historyKey",Crypto.b64(historyKey)).put("includesChats",chats);
   byte[] plain=core.toString().getBytes(Crypto.UTF8);byte[] sealed;try{sealed=RecoveryCipher.seal(plain,words);}finally{Arrays.fill(plain,(byte)0);}v.exportTransfer(history,historyKey,()->{},chats);RecoveryBundle.write(destination,sealed,history);
   String context=String.join("\n","priperi-recovery-register-v1",profile.getString("uid"),id,proof(v),KeyDelegation.digest(Crypto.certificates(chain)));
   return new Offer(words,destination,new JSONObject().put("id",id).put("chain",chain).put("signature",v.crypto().sign(context.getBytes(Crypto.UTF8))).put("uid",profile.getString("uid")));
  }catch(Exception e){Arrays.fill(words,(byte)0);destination.delete();throw e;}finally{Arrays.fill(historyKey,(byte)0);history.delete();}
 }
 static void register(Vault v,Offer offer)throws Exception{if(!offer.registration.getString("uid").equals(Session.uid())||v.transferIn()!=null||v.transferOut()!=null)throw new SecurityException("Account changed. Create the backup again.");Repository.call(v,"registerRecovery",offer.registration);}
 static void inspect(Vault v,File bundle,byte[] words)throws Exception{
  if(!v.emptyForTransfer())throw new SecurityException("Use an empty Priperi installation to recover an account.");if(v.transferIn()!=null||v.transferOut()!=null)throw new SecurityException("Finish the existing move or recovery first.");
  String temporary=TransferCipher.hash(UUID.randomUUID().toString().getBytes(Crypto.UTF8));File history=v.transferFile(temporary);byte[] plain=null;
  try{plain=RecoveryCipher.open(RecoveryBundle.unpack(bundle,history),words);JSONObject core=Vault.transferObject(plain);if(core.getInt("version")!=1)throw new SecurityException("Unsupported recovery backup.");GroupRepository.checkId(core.getString("id"));GroupRepository.checkId(core.getString("uid"));JSONObject profile=core.getJSONObject("profile"),identity=core.getJSONObject("identity");Crypto.verifyProfile(profile);Crypto.verifyPrivateIdentity(identity);if(!core.getString("uid").equals(profile.getString("uid"))||!identity.getString("fingerprint").equals(profile.getString("fingerprint"))||!identity.getString("hpke").equals(profile.getString("hpke"))||!identity.getString("signing").equals(profile.getString("signing"))||!identity.getString("historySecret").matches("[A-Za-z0-9_-]{43}"))throw new SecurityException("Recovery identity mismatch.");
   JSONArray prepared=core.getJSONArray("chain"),previous=profile.optJSONArray("delegations")==null?new JSONArray():profile.getJSONArray("delegations");if(prepared.length()!=previous.length()+1||prepared.length()>31)throw new SecurityException("Invalid recovery authorisation.");for(int i=0;i<previous.length();i++)if(!previous.getJSONObject(i).toString().equals(prepared.getJSONObject(i).toString()))throw new SecurityException("Invalid recovery authorisation.");
   List<String> keys=KeyDelegation.keys(core.getString("uid"),identity.getString("fingerprint"),identity.getString("signing"),Crypto.certificates(prepared));PrivateKey recovery=key(core.getString("authorizer"));String child=v.crypto().publicSigning(),context=KeyDelegation.context(core.getString("uid"),identity.getString("fingerprint"),keys.get(keys.size()-1),child),signature=KeyDelegation.sign(recovery,context.getBytes(Crypto.UTF8));if(!KeyDelegation.verify(keys.get(keys.size()-1),context.getBytes(Crypto.UTF8),signature))throw new SecurityException("Invalid recovery key.");JSONArray chain=new JSONArray(prepared.toString());chain.put(new JSONObject().put("key",child).put("signature",signature));
   byte[] hk=Crypto.unb64(core.getString("historyKey"));try{if(hk.length!=32)throw new SecurityException("Invalid chats key.");Vault.verifyTransfer(history,hk,profile);}finally{Arrays.fill(hk,(byte)0);}
   JSONObject pending=new JSONObject().put("recovery",true).put("uid",core.getString("uid")).put("id",core.getString("id")).put("identity",identity).put("profile",profile).put("chain",chain).put("authorizer",core.getString("authorizer")).put("historyKey",core.getString("historyKey")).put("historyFile",temporary).put("includesChats",core.getBoolean("includesChats"));v.transferIn(pending);
  }catch(Exception e){history.delete();throw e;}finally{if(plain!=null)Arrays.fill(plain,(byte)0);}
 }
 private static PrivateKey key(String encoded)throws Exception{return KeyFactory.getInstance("EC").generatePrivate(new PKCS8EncodedKeySpec(Crypto.unb64(encoded)));}
 private static JSONObject target(Vault v,JSONObject pending)throws Exception{return new JSONObject().put("installation",v.identity().getString("installation")).put("deviceId",v.identity().getString("deviceId")).put("signing",v.crypto().publicSigning()).put("chain",pending.getJSONArray("chain"));}
 private static String context(Vault v,JSONObject pending,JSONObject target,String nonce)throws Exception{return String.join("\n","priperi-recovery-accept-v1",pending.getString("id"),pending.getString("uid"),proof(v),target.getString("installation"),target.getString("deviceId"),target.getString("signing"),KeyDelegation.digest(Crypto.certificates(target.getJSONArray("chain"))),nonce);}
 private static JSONObject payload(Vault v,JSONObject pending,JSONObject target,String nonce)throws Exception{String context=context(v,pending,target,nonce);return new JSONObject().put("id",pending.getString("id")).put("uid",pending.getString("uid")).put("target",target).put("recoverySignature",KeyDelegation.sign(key(pending.getString("authorizer")),context.getBytes(Crypto.UTF8))).put("signature",v.crypto().sign(context.getBytes(Crypto.UTF8)));}
 static void restore(Vault v,char[] password)throws Exception{
  JSONObject pending=v.transferIn();if(pending==null||!pending.optBoolean("recovery"))throw new SecurityException("Choose a recovery backup first.");File history=v.transferFile(pending.getString("historyFile"));byte[] hk=Crypto.unb64(pending.getString("historyKey"));
  try{if(!pending.optBoolean("historySaved"))Vault.verifyTransfer(history,hk,pending.getJSONObject("profile"));
   if(v.account()==null){JSONObject target=target(v,pending),request=payload(v,pending,target,"challenge");String nonce=AccountTransfer.request(v,"recoveryChallenge",request).getString("nonce");JSONObject accepted=AccountTransfer.request(v,"recoverAccount",payload(v,pending,target,nonce).put("nonce",nonce).put("password",new String(password)));JSONObject profile=accepted.getJSONObject("account");if(!profile.getJSONArray("delegations").toString().equals(pending.getJSONArray("chain").toString()))throw new SecurityException("Recovery destination changed.");v.activateTransfer(pending,profile);}
   Session.continueAccount(v,null,new String(password));if(!pending.optBoolean("historySaved")){v.importTransfer(history,hk);v.historySaved();}Repository.call(v,"finishRecovery",new JSONObject().put("id",pending.getString("id")));v.transferIn(null);history.delete();
  }finally{Arrays.fill(hk,(byte)0);}
 }
 static void discardUnclaimed(Vault v)throws Exception{JSONObject pending=v.transferIn();if(pending==null||!pending.optBoolean("recovery")||v.account()!=null)throw new SecurityException("Finish this recovery before removing its local data.");v.transferFile(pending.getString("historyFile")).delete();v.transferIn(null);}
 private AccountRecovery(){}
}
